operation.add:
// Installed theme extensions (e.g. Termopab) — link to theme settings
$this->load->model('setting/extension');
$theme_extensions = $this->model_setting_extension->getExtensionsByType('theme');
foreach ($theme_extensions as $theme_ext) {
	$perm = 'extension/' . $theme_ext['extension'] . '/theme/' . $theme_ext['code'];
	if ($this->user->hasPermission('access', $perm) && is_file(DIR_EXTENSION . $theme_ext['extension'] . '/admin/controller/theme/' . $theme_ext['code'] . '.php')) {
		$this->load->language('extension/' . $theme_ext['extension'] . '/theme/' . $theme_ext['code'], $theme_ext['code']);
		$design[] = [
			'name'     => $this->language->get($theme_ext['code'] . '_heading_title'),
			'href'     => $this->url->link('extension/' . $theme_ext['extension'] . '/theme/' . $theme_ext['code'], 'user_token=' . $this->session->data['user_token'] . '&store_id=0'),
			'children' => []
		];
	}
}
